/* MedCalc Disease Reference v7 — 20 additional original clinical-reference modules. Educational synthesis; verify current local protocols, patient factors, contraindications and resistance data before clinical use. */
(function(){
const A=[
{id:'acute-kidney-injury',name:'Acute Kidney Injury',system:'Nephrology',summary:'Abrupt decline in kidney function causing accumulation of nitrogenous waste and disturbances of fluid, electrolyte and acid-base balance.',sections:{'Definition':['An increase in serum creatinine and/or reduction in urine output over a short interval, classified by current KDIGO staging.'],'Etiology & risk factors':['Prerenal hypoperfusion, intrinsic renal injury and postrenal obstruction are the major categories.','Sepsis, dehydration, nephrotoxins, contrast exposure, surgery, heart failure and urinary obstruction are common risks.'],'Pathogenesis / Pathophysiology':['Reduced renal perfusion lowers glomerular filtration; persistent ischemia can cause tubular epithelial injury and impaired autoregulation.','Tubular obstruction, back-leak of filtrate, inflammation and microvascular dysfunction contribute to intrinsic AKI.'],'Clinical features':['Reduced urine output, edema, fatigue, nausea or symptoms of the underlying illness may occur; AKI can also be clinically silent.','Look for volume depletion, sepsis, nephrotoxin exposure and bladder outlet obstruction.'],'Investigations':['Trend creatinine and urine output; check electrolytes, bicarbonate, urinalysis and urine microscopy.','Renal ultrasound is useful when obstruction is suspected or the cause is unclear.'],'Diagnostic approach':['Classify as prerenal, intrinsic or postrenal using history, examination, urine findings and imaging.','Review all medications and recent procedures; consider serology/biopsy when glomerular or interstitial disease is suspected.'],'Differential diagnosis':['CKD with acute worsening, obstruction, glomerulonephritis, acute interstitial nephritis, acute tubular injury and hepatorenal/cardiorenal syndromes.'],'Treatment':['Correct hypovolemia or shock while avoiding fluid overload; stop or adjust nephrotoxins and renally cleared drugs.','Treat sepsis, obstruction and the specific intrinsic renal cause.','Dialysis is considered for refractory hyperkalemia, severe acidosis, pulmonary edema/volume overload, uremic complications or selected toxin exposures.'],'Drug / dose reference':['Drug doses must be adjusted to current kidney function; avoid routine low-dose dopamine for AKI prevention.','For hyperkalemia, emergency therapies such as IV calcium plus insulin/dextrose and beta-agonist therapy are used according to severity and ECG findings.'],'Monitoring & follow-up':['Strict fluid balance, daily or more frequent electrolytes/creatinine in unstable patients, and recovery assessment after discharge.'],'Complications':['Hyperkalemia, metabolic acidosis, pulmonary edema, uremia, arrhythmia and progression to CKD.'],'Clinical pearls':['Urine output is an important diagnostic and prognostic variable; a normal-looking creatinine early in illness does not exclude evolving AKI.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Acute Kidney Injury",'KDIGO Acute Kidney Injury guidance']},
{id:'glomerulonephritis',name:'Nephritic Syndrome / Glomerulonephritis',system:'Nephrology',summary:'Inflammatory glomerular injury producing hematuria, variable proteinuria, reduced filtration and often hypertension.',sections:{'Definition':['Nephritic syndrome typically features glomerular hematuria, dysmorphic RBCs/RBC casts, proteinuria, hypertension and reduced GFR.'],'Etiology & risk factors':['Postinfectious GN, IgA nephropathy, lupus nephritis, ANCA-associated vasculitis and anti-GBM disease are important causes.'],'Pathogenesis / Pathophysiology':['Immune complexes, antibodies or pauci-immune inflammation injure glomerular capillaries.','Loss of filtration barrier integrity causes hematuria/proteinuria; inflammatory swelling reduces GFR and activates salt-retaining mechanisms.'],'Clinical features':['Tea/cola-colored urine, edema, hypertension and oliguria are typical; systemic vasculitic symptoms may provide the diagnostic clue.'],'Investigations':['Urinalysis and microscopy, creatinine/eGFR, urine protein quantification, complements, ANA, ANCA, anti-GBM and infection testing are selected according to presentation.','Kidney biopsy is often required when the diagnosis will alter treatment.'],'Diagnostic approach':['Determine whether the pattern is immune-complex, pauci-immune or anti-GBM mediated and look for systemic disease.'],'Differential diagnosis':['IgA nephropathy, postinfectious GN, lupus nephritis, vasculitis, anti-GBM disease, interstitial nephritis and non-glomerular hematuria.'],'Treatment':['Treat the cause; rapidly progressive GN may require urgent specialist assessment and immunosuppression.','Control edema and hypertension and use renin-angiotensin blockade when appropriate for persistent proteinuria, with attention to renal function and potassium.'],'Drug / dose reference':['High-dose corticosteroids are used in selected immune-mediated GN, often with a disease-specific induction agent.','Rituximab, cyclophosphamide or plasma exchange may be used in selected vasculitis/anti-GBM presentations according to specialist protocols.'],'Monitoring & follow-up':['Serial creatinine, urine protein, urinalysis, BP and treatment toxicity monitoring are essential.'],'Complications':['Rapid kidney failure, pulmonary hemorrhage in pulmonary-renal syndromes, severe hypertension and CKD.'],'Clinical pearls':['RBC casts and dysmorphic RBCs strongly support glomerular bleeding; pulmonary hemorrhage plus AKI is an emergency.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Glomerular Diseases",'KDIGO Glomerular Diseases guidance']},
{id:'pyelonephritis',name:'Acute Pyelonephritis',system:'Infectious Diseases / Nephrology',summary:'Bacterial infection of the renal pelvis and parenchyma, usually ascending from the lower urinary tract.',sections:{'Definition':['Upper urinary tract infection involving renal tissue, with systemic inflammatory features in many patients.'],'Etiology & risk factors':['Escherichia coli is the commonest pathogen; obstruction, stones, reflux, pregnancy, diabetes, catheters and resistant-organism exposure increase risk.'],'Pathogenesis / Pathophysiology':['Bacteria ascend from the bladder through the ureter and multiply in renal tissue.','Inflammatory infiltration causes interstitial edema and, when severe, abscess formation or sepsis.'],'Clinical features':['Fever, chills, flank pain, costovertebral-angle tenderness, dysuria, frequency, nausea and vomiting are common.'],'Investigations':['Urinalysis and urine culture are central; CBC, renal function and blood cultures are indicated in severe/systemic illness.','Imaging is considered for obstruction, stones, severe illness or failure to improve.'],'Diagnostic approach':['Differentiate uncomplicated pyelonephritis from complicated infection, obstruction and sepsis.'],'Differential diagnosis':['Renal colic, appendicitis, cholecystitis, PID, pneumonia and musculoskeletal flank pain.'],'Treatment':['Start empiric antibiotics based on severity and local resistance, then tailor to culture.','Hospitalize patients with sepsis, obstruction, inability to take oral therapy, pregnancy with systemic illness or major comorbidity.'],'Drug / dose reference':['Ceftriaxone 1 g IV once daily is a commonly used empiric inpatient option where appropriate.','Fluoroquinolone regimens may be used when susceptibility and local resistance permit; avoid inappropriate empiric use in high-resistance settings.','Drainage/decompression is urgent when infected obstruction is present.'],'Monitoring & follow-up':['Clinical response should begin within 48–72 hours; persistent fever or pain warrants reassessment for resistant infection, obstruction or abscess.'],'Complications':['Sepsis, renal/perinephric abscess, emphysematous infection and renal scarring.'],'Clinical pearls':['Pyelonephritis plus obstruction is a urologic emergency requiring source control, not antibiotics alone.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Urinary Tract Infection",'IDSA/EAU urinary infection guidance']},
{id:'acute-cystitis',name:'Acute Cystitis / Urinary Tract Infection',system:'Infectious Diseases',summary:'Acute infection of the urinary bladder, usually caused by ascending enteric gram-negative bacteria.',sections:{'Definition':['Acute uncomplicated cystitis is a symptomatic lower UTI without features suggesting upper-tract or systemic infection.'],'Etiology & risk factors':['E. coli predominates; recent antibiotics, sexual activity, pregnancy, urinary abnormalities, diabetes and catheterization modify risk.'],'Pathogenesis / Pathophysiology':['Uropathogens colonize the periurethral area and ascend into the bladder, adhering to urothelium and triggering local inflammation.'],'Clinical features':['Dysuria, frequency, urgency and suprapubic discomfort are typical; fever or flank pain suggests upper-tract disease.'],'Investigations':['Urinalysis supports diagnosis; urine culture is particularly important in pregnancy, recurrent/complicated infection or treatment failure.'],'Diagnostic approach':['Use symptoms plus urinalysis/culture selectively; do not treat asymptomatic bacteriuria except in established indications such as pregnancy or before selected urologic procedures.'],'Differential diagnosis':['Vaginitis, urethritis/STI, interstitial cystitis and nephrolithiasis.'],'Treatment':['Choose a short-course antibiotic according to local resistance, sex, pregnancy status and complicated features.','Hydration and analgesia can support symptom control.'],'Drug / dose reference':['Nitrofurantoin 100 mg orally twice daily for 5 days is a common adult uncomplicated-cystitis regimen when renal function and organism susceptibility are appropriate.','Fosfomycin trometamol 3 g orally as a single dose is another option for selected uncomplicated cases.'],'Monitoring & follow-up':['Reassess if symptoms persist, recur quickly or systemic features develop; obtain culture in recurrent/complicated cases.'],'Complications':['Pyelonephritis, recurrent UTI and, in high-risk patients, sepsis.'],'Clinical pearls':['New fever, rigors, flank pain or vomiting should prompt evaluation for pyelonephritis rather than treating as simple cystitis.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Urinary Tract Infection",'EAU Guidelines on Urological Infections']},
{id:'benign-prostatic-hyperplasia',name:'Benign Prostatic Hyperplasia',system:'Urology',summary:'Nonmalignant enlargement of prostatic tissue that can cause bladder outlet obstruction and lower urinary tract symptoms.',sections:{'Definition':['BPH refers to benign stromal and epithelial proliferation, while the clinical syndrome includes lower urinary tract symptoms and/or bladder outlet obstruction.'],'Etiology & risk factors':['Age and androgen-dependent prostatic growth are major factors; obesity and metabolic disease may contribute.'],'Pathogenesis / Pathophysiology':['Hyperplasia in the transition zone increases static urethral resistance, while increased smooth-muscle tone adds a dynamic component.','Chronic obstruction can cause detrusor hypertrophy, instability and eventually impaired bladder contractility.'],'Clinical features':['Frequency, urgency, nocturia, weak stream, hesitancy, intermittency and incomplete emptying are common.'],'Investigations':['History, symptom score, abdominal/genital exam and DRE are typical; urinalysis and selected renal tests help exclude complications.','Post-void residual and prostate assessment are used when clinically indicated; PSA is considered according to shared decision-making.'],'Diagnostic approach':['Assess symptom severity, complications, prostate size and alternative causes before treatment.'],'Differential diagnosis':['Prostate cancer, urethral stricture, neurogenic bladder, UTI, bladder pathology and medication effects.'],'Treatment':['Watchful waiting with lifestyle measures is reasonable for mild symptoms.','Alpha-1 blockers provide rapid symptom relief; 5-alpha-reductase inhibitors are useful when prostate enlargement is substantial.','Refractory symptoms, retention, recurrent infection, stones or renal impairment may require procedural therapy.'],'Drug / dose reference':['Tamsulosin 0.4 mg once daily is a common starting dose.','Finasteride 5 mg once daily reduces prostate volume over months and lowers progression risk.','Tadalafil 5 mg once daily can improve LUTS in selected men; consider contraindications and drug interactions.'],'Monitoring & follow-up':['Review symptom response, BP/dizziness with alpha-blockers, sexual adverse effects and PSA interpretation with 5-alpha-reductase inhibitors.'],'Complications':['Acute urinary retention, recurrent UTI, bladder stones, hematuria and obstructive renal dysfunction.'],'Clinical pearls':['5-alpha-reductase inhibitors work slowly; alpha-blockers improve symptoms faster but do not shrink the prostate.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Disorders of the Prostate",'EAU Guidelines on Management of Non-neurogenic Male LUTS']},
{id:'peptic-ulcer-disease',name:'Peptic Ulcer Disease',system:'Gastroenterology',summary:'Mucosal ulceration in the stomach or proximal duodenum caused by acid-peptic injury, most commonly related to H. pylori or NSAIDs.',sections:{'Definition':['A mucosal defect extending through the muscularis mucosae in the stomach or duodenum, usually caused by H. pylori or NSAID-related injury.'],'Etiology & risk factors':['H. pylori, NSAIDs, aspirin, smoking and severe physiologic stress are important causes; hypersecretory states are uncommon.'],'Pathogenesis / Pathophysiology':['H. pylori disrupts mucosal defenses and alters acid regulation; NSAIDs inhibit prostaglandin synthesis, reducing mucus, bicarbonate and mucosal blood flow.','Acid and pepsin then overwhelm epithelial repair and produce ulceration.'],'Clinical features':['Epigastric burning or pain, dyspepsia, nausea and meal-related symptoms may occur; bleeding or perforation can be the first presentation.'],'Investigations':['Test for H. pylori using urea breath test, stool antigen or biopsy-based testing as appropriate.','Endoscopy is indicated for alarm features, suspected bleeding/perforation or selected higher-risk presentations.'],'Diagnostic approach':['Identify H. pylori/NSAID exposure and assess for complications; biopsy suspicious gastric lesions.'],'Differential diagnosis':['GERD, functional dyspepsia, gastritis, pancreatitis, biliary disease and gastric malignancy.'],'Treatment':['Eradicate H. pylori when present using a current guideline-concordant regimen and confirm eradication.','Stop NSAIDs when possible; if essential, use gastroprotection and the lowest effective dose.','PPI therapy promotes ulcer healing.'],'Drug / dose reference':['Omeprazole 20 mg once or twice daily is a common acid-suppression dose depending on indication.','Bismuth quadruple therapy for H. pylori commonly combines a PPI, bismuth, tetracycline and metronidazole for 14 days; use current local resistance guidance.'],'Monitoring & follow-up':['Confirm H. pylori eradication after therapy using an appropriate test and timing; reassess persistent symptoms or alarm features.'],'Complications':['Upper GI bleeding, perforation, penetration, gastric outlet obstruction and recurrent ulceration.'],'Clinical pearls':['A bleeding ulcer requires stabilization and endoscopic hemostasis when indicated; acid suppression alone is not definitive therapy for major hemorrhage.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Peptic Ulcer Disease",'ACG guideline on H. pylori infection']},
{id:'upper-gi-bleeding',name:'Upper Gastrointestinal Bleeding',system:'Gastroenterology / Emergency Medicine',summary:'Hemorrhage arising proximal to the ligament of Treitz, commonly from peptic ulcer disease or portal-hypertensive lesions.',sections:{'Definition':['Acute bleeding from the esophagus, stomach or duodenum presenting with hematemesis, coffee-ground emesis and/or melena.'],'Etiology & risk factors':['Peptic ulcer disease, varices, erosive disease and Mallory-Weiss tears are common causes; NSAIDs, anticoagulants, liver disease and H. pylori increase risk.'],'Pathogenesis / Pathophysiology':['Mucosal ulceration or vascular disruption causes arterial or venous hemorrhage.','Rapid blood loss reduces circulating volume and oxygen delivery, producing tachycardia, hypotension and shock when severe.'],'Clinical features':['Hematemesis, melena, weakness, syncope, tachycardia and hypotension may occur.','Assess for chronic liver disease and signs of portal hypertension.'],'Investigations':['CBC, urea/creatinine, electrolytes, coagulation profile, liver tests and type/crossmatch support resuscitation.','Use a validated pre-endoscopic score such as Glasgow-Blatchford; upper endoscopy establishes diagnosis and enables therapy.'],'Diagnostic approach':['Stabilize first, risk-stratify, then perform timely endoscopy; suspect variceal bleeding in appropriate patients with cirrhosis.'],'Differential diagnosis':['Swallowed blood, hemoptysis, lower GI bleeding with rapid transit and non-GI causes of syncope.'],'Treatment':['Resuscitate with appropriate IV access and blood products based on clinical status and restrictive transfusion strategies where suitable.','Endoscopic hemostasis is standard for high-risk nonvariceal bleeding.','Suspected variceal bleeding requires vasoactive therapy plus prophylactic antibiotics and urgent endoscopic band ligation when indicated.'],'Drug / dose reference':['Pantoprazole 80 mg IV loading dose followed by 8 mg/hour infusion is a commonly used high-risk ulcer-bleed regimen where IV PPI infusion is selected.','Octreotide 50 micrograms IV bolus followed by 50 micrograms/hour infusion is commonly used for suspected variceal hemorrhage.','Ceftriaxone 1 g IV daily is commonly used for antibiotic prophylaxis in acute variceal bleeding, subject to local protocol.'],'Monitoring & follow-up':['Monitor hemodynamics, hemoglobin, renal function and rebleeding; repeat endoscopy or interventional radiology is considered for recurrent bleeding.'],'Complications':['Hemorrhagic shock, aspiration, rebleeding, acute kidney injury and death.'],'Clinical pearls':['In suspected variceal bleeding, begin vasoactive therapy and antibiotics promptly rather than waiting for endoscopy.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Gastrointestinal Hemorrhage",'ACG/ESGE upper GI bleeding guidance; Baveno consensus']},
{id:'lower-gi-bleeding',name:'Lower Gastrointestinal Bleeding',system:'Gastroenterology / Emergency Medicine',summary:'Bleeding originating distal to the ligament of Treitz, often presenting with hematochezia.',sections:{'Definition':['Acute hematochezia or maroon stool from a lower GI source; brisk upper GI bleeding can occasionally present similarly.'],'Etiology & risk factors':['Diverticular bleeding, angioectasia, ischemic colitis, inflammatory bowel disease, hemorrhoids and colorectal neoplasia are important causes.'],'Pathogenesis / Pathophysiology':['Mucosal ulceration, vascular ectasia, diverticular arterial rupture or ischemic injury disrupts intestinal vessels.','Severity depends on bleeding rate, vessel caliber and reserve of the patient.'],'Clinical features':['Bright-red or maroon blood per rectum, dizziness, weakness and abdominal pain in selected etiologies.'],'Investigations':['Assess vitals, CBC, renal function, coagulation and type/crossmatch.','CTA is useful in ongoing hemodynamically significant bleeding; colonoscopy is used after stabilization in appropriate patients.'],'Diagnostic approach':['Exclude an upper source when clinically indicated and localize active bleeding using CTA/endoscopy.'],'Differential diagnosis':['Upper GI bleeding, anorectal bleeding, IBD, ischemic colitis, diverticular disease and colorectal cancer.'],'Treatment':['Resuscitate and correct major coagulopathy where appropriate.','Endoscopic, angiographic or surgical hemostasis depends on source and severity.','Review anticoagulant/antiplatelet therapy and balance bleeding control with thrombotic risk.'],'Drug / dose reference':['Medication therapy is cause-specific; routine empiric PPI is not a substitute for localization of significant lower GI bleeding.','Tranexamic acid is not routinely recommended for undifferentiated GI bleeding because benefit-risk depends on the clinical setting.'],'Monitoring & follow-up':['Serial hemoglobin and hemodynamics; investigate recurrent or unexplained bleeding for malignancy, vascular lesions or IBD.'],'Complications':['Shock, anemia, recurrent hemorrhage, ischemic complications and missed colorectal cancer.'],'Clinical pearls':['Hematochezia with shock may be brisk upper GI bleeding; do not assume every red stool is a colonic source.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Gastrointestinal Hemorrhage",'ACG guideline on acute lower GI bleeding']},
{id:'acute-appendicitis',name:'Acute Appendicitis',system:'Gastroenterology / Surgery',summary:'Acute inflammation of the vermiform appendix, usually following luminal obstruction and bacterial overgrowth.',sections:{'Definition':['Acute inflammation of the appendix that may progress from uncomplicated disease to gangrene, perforation and abscess.'],'Etiology & risk factors':['Fecalith, lymphoid hyperplasia and other luminal obstruction can initiate disease; risk varies with age and host factors.'],'Pathogenesis / Pathophysiology':['Luminal obstruction raises intraluminal pressure, impairs venous/lymphatic drainage and promotes bacterial proliferation.','Ischemia progresses to transmural inflammation, necrosis and possible perforation.'],'Clinical features':['Periumbilical pain migrating to the right lower quadrant, anorexia, nausea, vomiting and localized tenderness are classic.'],'Investigations':['CBC and inflammatory markers support assessment; pregnancy testing is appropriate when relevant.','Ultrasound, CT or MRI is selected according to age, pregnancy status and diagnostic uncertainty.'],'Diagnostic approach':['Use clinical assessment with a validated score when helpful, but do not let a score replace imaging or surgical evaluation when uncertainty remains.'],'Differential diagnosis':['Mesenteric adenitis, gastroenteritis, renal colic, ectopic pregnancy, ovarian pathology, Crohn disease and diverticulitis.'],'Treatment':['Uncomplicated disease is commonly treated with appendectomy; selected patients may receive antibiotics with careful follow-up.','Perforation/abscess requires antibiotics and source control, with drainage or surgery according to anatomy and expertise.'],'Drug / dose reference':['Ceftriaxone plus metronidazole is a commonly used perioperative/empiric combination; exact dosing follows local surgical protocol.','Analgesia and antiemetics are supportive.'],'Monitoring & follow-up':['Monitor for fever, worsening pain, leukocytosis, ileus and postoperative complications.'],'Complications':['Perforation, abscess, peritonitis, sepsis and postoperative wound/intra-abdominal infection.'],'Clinical pearls':['Pain migration is helpful but not universal; atypical anatomy and pregnancy can substantially alter presentation.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Acute Appendicitis",'WSES Jerusalem guidelines on acute appendicitis']},
{id:'intestinal-obstruction',name:'Intestinal Obstruction',system:'Gastroenterology / Surgery',summary:'Mechanical or functional interruption of intestinal contents causing bowel dilation, vomiting, fluid shifts and possible ischemia.',sections:{'Definition':['Mechanical obstruction prevents passage of intestinal contents; ileus is functional hypomotility without a mechanical blockage.'],'Etiology & risk factors':['Adhesions, hernias and tumors are common mechanical causes; volvulus, strictures and inflammatory disease are other causes.'],'Pathogenesis / Pathophysiology':['Proximal accumulation of fluid and gas increases bowel pressure, causing distension, vomiting and third-spacing.','Progressive pressure can impair venous drainage, then arterial perfusion, leading to strangulation, necrosis and perforation.'],'Clinical features':['Colicky abdominal pain, vomiting, distension and obstipation are typical; severe continuous pain suggests ischemia.'],'Investigations':['Electrolytes, CBC, lactate and renal function assess physiologic impact.','CT abdomen/pelvis is highly useful for identifying level, cause and ischemia; plain radiography has a limited adjunctive role.'],'Diagnostic approach':['Determine mechanical versus functional obstruction and look urgently for closed-loop obstruction, strangulation or perforation.'],'Differential diagnosis':['Ileus, gastroenteritis, mesenteric ischemia, severe constipation and pseudo-obstruction.'],'Treatment':['NPO, IV fluids, electrolyte correction and nasogastric decompression are used when indicated.','Urgent surgery is required for strangulation, ischemia, perforation, peritonitis or selected complete/closed-loop obstruction.','Treat the underlying cause and provide antibiotics when ischemia/perforation or surgery warrants them.'],'Drug / dose reference':['Analgesia and antiemetics are supportive; avoid routine laxatives in suspected complete mechanical obstruction.','Broad-spectrum antibiotics are indicated when bowel ischemia, perforation or operative management is suspected.'],'Monitoring & follow-up':['Serial abdominal examinations, urine output, electrolytes, lactate and imaging when clinical status changes.'],'Complications':['Bowel ischemia, necrosis, perforation, aspiration, sepsis and short-bowel consequences after extensive resection.'],'Clinical pearls':['Pain out of proportion, metabolic acidosis or rising lactate should heighten concern for bowel ischemia.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Intestinal Obstruction",'WSES small-bowel obstruction guidance']},
{id:'colorectal-cancer',name:'Colorectal Cancer',system:'Oncology / Gastroenterology',summary:'Malignant neoplasm of the colon or rectum, arising through accumulated genetic and epigenetic alterations.',sections:{'Definition':['Adenocarcinoma is the predominant colorectal malignancy and may develop from precursor adenomas or through serrated pathways.'],'Etiology & risk factors':['Age, family history, hereditary syndromes, inflammatory bowel disease, obesity, smoking, alcohol, diet and metabolic factors influence risk.'],'Pathogenesis / Pathophysiology':['Accumulation of driver alterations disrupts APC/WNT, RAS/MAPK, TP53 and DNA-repair pathways in major tumorigenic routes.','Progression from mucosal precursor lesion to invasive cancer enables lymphatic and hematogenous spread, especially to liver and lung.'],'Clinical features':['Rectal bleeding, iron-deficiency anemia, altered bowel habit, abdominal pain and weight loss may occur; early disease can be asymptomatic.'],'Investigations':['Colonoscopy with biopsy establishes diagnosis.','CBC, liver tests, CEA for baseline/follow-up, CT staging and selected MRI pelvis for rectal cancer are standard components of staging.','Molecular testing includes mismatch-repair/MSI status and other biomarkers that guide systemic therapy.'],'Diagnostic approach':['Confirm histology, determine anatomic stage and assess molecular features before definitive systemic treatment.'],'Differential diagnosis':['Hemorrhoids, IBD, diverticular disease, infectious colitis and benign polyps.'],'Treatment':['Localized disease is treated primarily with surgery, with chemotherapy/radiotherapy according to stage and rectal anatomy.','Metastatic disease uses biomarker-directed and combination systemic therapy; selected liver/lung metastases may be resectable.'],'Drug / dose reference':['5-fluorouracil/capecitabine, oxaliplatin and irinotecan are common chemotherapy components; regimens and dosing are oncology-protocol specific.','Targeted or immune therapies depend on RAS/BRAF, HER2, MSI/MMR and other biomarkers.'],'Monitoring & follow-up':['Surveillance includes clinical review, CEA when informative, interval imaging and colonoscopy according to stage and guideline.'],'Complications':['Obstruction, perforation, bleeding, anemia, metastases and treatment toxicity.'],'Clinical pearls':['Iron-deficiency anemia in an adult without an obvious source warrants evaluation for GI blood loss, including colorectal pathology when appropriate.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Colorectal Cancer",'NCCN/ESMO colorectal cancer guidance']},
{id:'hepatocellular-carcinoma',name:'Hepatocellular Carcinoma',system:'Hepatology / Oncology',summary:'Primary malignant tumor of hepatocytes, commonly arising in a chronically diseased or cirrhotic liver.',sections:{'Definition':['The major primary liver cancer arising from hepatocytes; risk is strongly associated with chronic liver disease.'],'Etiology & risk factors':['Cirrhosis, chronic hepatitis B or C, alcohol-associated liver disease, metabolic dysfunction-associated steatotic liver disease and aflatoxin exposure increase risk.'],'Pathogenesis / Pathophysiology':['Chronic inflammation and regeneration produce genomic instability, fibrosis and malignant transformation.','Tumor angiogenesis and portal/hepatic venous invasion facilitate local progression and metastasis.'],'Clinical features':['Often asymptomatic under surveillance; weight loss, RUQ pain, decompensation or a new liver mass may occur.'],'Investigations':['In at-risk patients, multiphasic contrast CT or MRI can establish a characteristic radiologic diagnosis in appropriate lesions.','AFP may support assessment but is not sufficiently sensitive or specific to diagnose HCC alone.'],'Diagnostic approach':['Stage by tumor burden, vascular invasion, extrahepatic spread and liver function/performance status.'],'Differential diagnosis':['Intrahepatic cholangiocarcinoma, metastasis, hepatic adenoma and regenerative/dysplastic nodules.'],'Treatment':['Curative options include resection, ablation and transplantation in selected patients.','Transarterial therapies and systemic therapy are used for unresectable disease according to stage and liver function.'],'Drug / dose reference':['Systemic therapy may include immunotherapy-based combinations or targeted agents selected by current guideline and patient factors; dosing is oncology-protocol specific.'],'Monitoring & follow-up':['Patients with cirrhosis or high-risk HBV require guideline-based surveillance; post-treatment imaging assesses response.'],'Complications':['Portal vein invasion, rupture/hemorrhage, liver failure, metastases and cancer-related cachexia.'],'Clinical pearls':['In a cirrhotic patient, a new arterial-enhancing lesion with appropriate washout on multiphasic imaging may establish HCC without biopsy in selected guideline-defined settings.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Hepatocellular Carcinoma",'AASLD guidance on HCC']},
{id:'acute-liver-failure',name:'Acute Liver Failure',system:'Hepatology / Critical Care',summary:'Rapid development of severe hepatic dysfunction with coagulopathy and encephalopathy in a person without established cirrhosis.',sections:{'Definition':['Acute liver failure classically involves acute severe liver injury, INR elevation and hepatic encephalopathy without pre-existing cirrhosis.'],'Etiology & risk factors':['Acetaminophen toxicity, viral hepatitis, autoimmune hepatitis, ischemia and drug-induced liver injury are major causes.'],'Pathogenesis / Pathophysiology':['Massive hepatocyte injury causes loss of synthetic, metabolic and detoxification functions.','Ammonia accumulation, cerebral astrocyte swelling, systemic inflammation and altered cerebral blood flow contribute to encephalopathy and cerebral edema.'],'Clinical features':['Jaundice, nausea, abdominal discomfort, coagulopathy and altered mental status may progress rapidly.','Hypoglycemia, renal failure, hypotension and cerebral edema are important complications.'],'Investigations':['Urgently check INR/PT, glucose, AST/ALT, bilirubin, creatinine, electrolytes, ammonia and blood gas when indicated.','Investigate acetaminophen level/toxicology, viral serology and autoimmune markers; ultrasound with Doppler can assess vascular causes.'],'Diagnostic approach':['Identify cause immediately while simultaneously assessing encephalopathy, cerebral edema, renal failure and transplant eligibility.'],'Differential diagnosis':['Acute-on-chronic liver failure, severe hepatitis without failure, sepsis-associated cholestasis and Wilson disease.'],'Treatment':['ICU-level supportive care and early referral to a liver-transplant center are essential.','Give N-acetylcysteine promptly for acetaminophen toxicity and consider it in selected non-acetaminophen ALF.','Treat hypoglycemia, infection, cerebral edema and renal failure; avoid unnecessary sedatives.'],'Drug / dose reference':['N-acetylcysteine for acetaminophen poisoning is commonly given by weight-based IV protocols; a standard 21-hour regimen uses 300 mg/kg total.','Hypertonic saline may be used for selected patients at high risk of cerebral edema under critical-care protocols.'],'Monitoring & follow-up':['Frequent neurologic, glucose, INR, renal, electrolyte and hemodynamic monitoring; early transplant assessment is critical.'],'Complications':['Cerebral edema/herniation, severe hypoglycemia, renal failure, infection, shock and multiorgan failure.'],'Clinical pearls':['Do not delay transfer to a transplant-capable center while waiting for complete etiologic work-up.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Acute Liver Failure",'AASLD acute liver failure guidance']},
{id:'alcohol-associated-liver-disease',name:'Alcohol-Associated Liver Disease',system:'Hepatology',summary:'Spectrum of hepatic injury caused by chronic alcohol exposure, ranging from steatosis to steatohepatitis, fibrosis and cirrhosis.',sections:{'Definition':['Alcohol-associated liver disease includes alcohol-related steatosis, hepatitis, fibrosis and cirrhosis.'],'Etiology & risk factors':['Cumulative alcohol exposure is central; obesity, metabolic disease, sex, genetics and nutritional status modify risk.'],'Pathogenesis / Pathophysiology':['Ethanol metabolism increases acetaldehyde and oxidative stress, alters lipid metabolism and promotes hepatocyte injury.','Gut-liver axis dysfunction and innate immune activation amplify inflammation and fibrogenesis.'],'Clinical features':['Steatosis may be silent; alcohol-associated hepatitis can cause jaundice, fever, tender hepatomegaly and systemic inflammation.','Cirrhosis produces portal hypertension and hepatic decompensation.'],'Investigations':['Liver enzymes, bilirubin, INR, albumin, CBC, renal function and ultrasound/elastography assess injury and fibrosis.','Exclude viral, autoimmune and obstructive causes when appropriate.'],'Diagnostic approach':['Assess alcohol exposure accurately, determine severity of hepatitis/cirrhosis and screen for complications and nutritional deficiencies.'],'Differential diagnosis':['Viral hepatitis, MASLD, autoimmune hepatitis, drug-induced liver injury and biliary disease.'],'Treatment':['Complete alcohol abstinence is the key disease-modifying intervention.','Treat alcohol withdrawal safely, optimize nutrition and manage cirrhosis complications.','Severe alcohol-associated hepatitis may qualify for corticosteroids after careful exclusion of contraindications; transplant is considered in selected advanced disease.'],'Drug / dose reference':['Thiamine 100 mg daily or higher parenteral doses in selected high-risk hospitalized patients are used to prevent/treat deficiency according to local protocol.','Prednisolone 40 mg daily for 28 days is a commonly studied regimen for selected severe alcohol-associated hepatitis after infection/GI bleeding assessment.'],'Monitoring & follow-up':['Track abstinence, nutrition, liver/renal function, portal-hypertension complications and hepatocellular-carcinoma surveillance when cirrhosis is present.'],'Complications':['Cirrhosis, portal hypertension, variceal bleeding, ascites, encephalopathy, HCC and acute-on-chronic liver failure.'],'Clinical pearls':['Treating alcohol use disorder is central to liver prognosis; hepatology care should be paired with evidence-based addiction treatment.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Alcohol-Associated Liver Disease",'AASLD alcohol-associated liver disease guidance']},
{id:'type-2-diabetes-mellitus',name:'Type 2 Diabetes Mellitus',system:'Endocrinology',summary:'Metabolic disease characterized by chronic hyperglycemia from insulin resistance with progressive beta-cell dysfunction.',sections:{'Definition':['Diabetes is diagnosed using established plasma glucose or HbA1c thresholds, confirmed when required by the clinical setting.'],'Etiology & risk factors':['Genetic susceptibility, obesity, physical inactivity, age, family history, gestational diabetes and cardiometabolic disease increase risk.'],'Pathogenesis / Pathophysiology':['Insulin resistance increases hepatic glucose output and reduces peripheral glucose uptake.','Progressive beta-cell dysfunction reduces insulin secretion; altered incretin signaling, adipose inflammation and glucotoxicity contribute.'],'Clinical features':['Polyuria, polydipsia, weight change, blurred vision and recurrent infections may occur, but many patients are asymptomatic.'],'Investigations':['HbA1c, fasting plasma glucose or oral glucose tolerance testing establish diagnosis; assess renal function, urine albumin, lipids, BP and cardiovascular risk.','Screen for retinopathy, neuropathy and foot disease according to duration and risk.'],'Diagnostic approach':['Confirm diagnosis when appropriate and determine whether autoimmune diabetes, secondary diabetes or hyperglycemic crisis is more likely.'],'Differential diagnosis':['Type 1 diabetes, LADA, pancreatic diabetes, endocrine disorders and medication-induced hyperglycemia.'],'Treatment':['Lifestyle intervention is foundational.','Use metformin when appropriate and choose additional agents based on ASCVD, heart failure, CKD, weight and hypoglycemia considerations.','GLP-1 receptor agonists/GIP-GLP-1 therapy and SGLT2 inhibitors have important cardiorenal/weight benefits in selected patients.'],'Drug / dose reference':['Metformin commonly starts at 500 mg once or twice daily with food and is titrated as tolerated; renal function determines eligibility.','Empagliflozin 10 mg once daily is a common SGLT2 inhibitor dose in eligible patients.','Semaglutide is initiated at a low weekly dose and titrated gradually according to the indication and product labeling.'],'Monitoring & follow-up':['HbA1c is typically reassessed about every 3 months when therapy changes or targets are unmet; monitor renal function and treatment-specific adverse effects.'],'Complications':['Retinopathy, nephropathy, neuropathy, ASCVD, heart failure, infection and hyperglycemic crises.'],'Clinical pearls':['Drug choice should be individualized to comorbidities rather than treating HbA1c in isolation.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Diabetes Mellitus",'ADA Standards of Care in Diabetes']},
{id:'diabetic-hypoglycemia',name:'Diabetic Hypoglycemia',system:'Endocrinology / Emergency Medicine',summary:'Abnormally low plasma glucose in a person with diabetes, most often caused by insulin or insulin-secretagogue therapy.',sections:{'Definition':['Clinically important hypoglycemia is generally recognized at glucose below 70 mg/dL, with lower levels increasing risk of neuroglycopenia and severe events.'],'Etiology & risk factors':['Insulin, sulfonylureas, missed meals, exercise, alcohol, renal impairment and acute illness are common contributors.'],'Pathogenesis / Pathophysiology':['Falling glucose normally suppresses insulin and increases glucagon, epinephrine and other counter-regulatory hormones.','Exogenous insulin or impaired counter-regulation can prevent adequate recovery, producing autonomic and neuroglycopenic symptoms.'],'Clinical features':['Sweating, tremor, palpitations, hunger, anxiety, confusion, visual change, seizures and coma may occur.'],'Investigations':['Check capillary or plasma glucose immediately; evaluate medication timing, food intake, renal function and recurrent episodes.','If unexplained/recurrent, consider endocrine or critical-illness causes.'],'Diagnostic approach':['Confirm low glucose when possible and assess Whipple-type clinical response; identify the responsible drug and precipitant.'],'Differential diagnosis':['Syncope, seizure, intoxication, stroke and other causes of altered mental status.'],'Treatment':['If conscious and able to swallow, give about 15–20 g rapid-acting carbohydrate and recheck glucose after 15 minutes; repeat if needed.','Severe hypoglycemia requires IV dextrose or glucagon when IV access is unavailable.','Sulfonylurea-associated recurrent hypoglycemia may require octreotide and prolonged observation.'],'Drug / dose reference':['Glucagon 1 mg IM/SC is a traditional adult rescue dose; newer ready-to-use products have product-specific dosing.','IV dextrose concentration and dose depend on access and severity; avoid overly rapid overcorrection when possible.'],'Monitoring & follow-up':['Recheck glucose after treatment and observe longer for long-acting insulin or sulfonylurea exposure; adjust the diabetes regimen to prevent recurrence.'],'Complications':['Seizures, trauma, arrhythmia, cognitive injury and death.'],'Clinical pearls':['Treat first—do not delay glucose correction while searching for the cause.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Hypoglycemia",'ADA Standards of Care in Diabetes']},
{id:'hyperthyroidism',name:'Hyperthyroidism / Thyrotoxicosis',system:'Endocrinology',summary:'Clinical state caused by excessive thyroid hormone action; hyperthyroidism specifically denotes increased endogenous thyroid hormone synthesis.',sections:{'Definition':['Thyrotoxicosis is excess thyroid hormone action from any cause; Graves disease and toxic nodular disease are common causes of true hyperthyroidism.'],'Etiology & risk factors':['Graves disease, toxic multinodular goiter, toxic adenoma, thyroiditis and exogenous hormone exposure are important causes.'],'Pathogenesis / Pathophysiology':['Excess T3/T4 increases beta-adrenergic sensitivity and basal metabolic activity, producing tachycardia, heat production and increased catabolism.','Autoimmune TSH-receptor stimulation causes diffuse thyroid hyperfunction in Graves disease.'],'Clinical features':['Weight loss, heat intolerance, tremor, palpitations, anxiety, diarrhea and proximal weakness are common; Graves may cause ophthalmopathy.'],'Investigations':['TSH is usually suppressed with elevated free T4 and/or T3.','TSH-receptor antibodies support Graves; uptake scanning helps distinguish hyperfunction from thyroiditis when appropriate.'],'Diagnostic approach':['Confirm biochemical thyrotoxicosis and determine its cause before definitive treatment.'],'Differential diagnosis':['Anxiety, pheochromocytoma, medication effects, thyroiditis, exogenous hormone and systemic illness.'],'Treatment':['Beta-blockade controls adrenergic symptoms.','Antithyroid drugs, radioactive iodine or surgery are selected based on cause, pregnancy status, goiter/ophthalmopathy and patient preference.'],'Drug / dose reference':['Methimazole is commonly started around 10–30 mg/day depending on severity, then titrated to thyroid tests.','Propranolol 20–40 mg orally every 6–8 hours is a common symptomatic regimen when not contraindicated.','Propylthiouracil is preferred in selected situations such as first-trimester pregnancy and thyroid storm.'],'Monitoring & follow-up':['Monitor free T4/T3 initially and later TSH; counsel about agranulocytosis and hepatic toxicity from antithyroid drugs.'],'Complications':['Atrial fibrillation, heart failure, osteoporosis, muscle wasting and thyroid storm.'],'Clinical pearls':['New fever, delirium, severe tachycardia and GI/hepatic symptoms in thyrotoxicosis should raise concern for thyroid storm.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Thyrotoxicosis",'American Thyroid Association guidance']},
{id:'thyroid-storm',name:'Thyroid Storm',system:'Endocrinology / Critical Care',summary:'Life-threatening decompensated thyrotoxicosis with systemic organ dysfunction.',sections:{'Definition':['A clinical diagnosis of severe thyrotoxicosis with fever, cardiovascular and CNS/GI/hepatic decompensation; no single laboratory value establishes the diagnosis.'],'Etiology & risk factors':['Untreated Graves disease, infection, surgery, trauma, iodine exposure and abrupt withdrawal of antithyroid therapy can precipitate storm.'],'Pathogenesis / Pathophysiology':['Excess thyroid hormone amplifies catecholamine responsiveness, increases metabolic demand and causes hyperthermia, tachyarrhythmia and high-output cardiovascular stress.','Systemic decompensation leads to heart failure, shock, delirium and hepatic dysfunction.'],'Clinical features':['High fever, marked tachycardia, agitation/delirium, vomiting/diarrhea, heart failure and sometimes jaundice.'],'Investigations':['TSH, free T4/T3, CBC, electrolytes, glucose, liver/renal function, ECG and cultures when infection is suspected.','Use a validated clinical scoring framework as an adjunct, not as a substitute for clinical judgment.'],'Diagnostic approach':['Treat immediately when strongly suspected while searching for and controlling the precipitating factor.'],'Differential diagnosis':['Sepsis, malignant hyperthermia, serotonin syndrome, neuroleptic malignant syndrome and pheochromocytoma crisis.'],'Treatment':['ICU care, cooling, fluids tailored to cardiac status, treatment of precipitant and rapid blockade of thyroid hormone effects and synthesis.','Beta-blockade, antithyroid medication, iodine after thionamide, and corticosteroids are standard components unless contraindicated.'],'Drug / dose reference':['Propylthiouracil 500–1000 mg loading dose followed by 250 mg every 4 hours is a commonly used regimen.','Iodine solution is given at least about 1 hour after thionamide to block hormone release.','Hydrocortisone 100 mg IV every 8 hours is a commonly used regimen.'],'Monitoring & follow-up':['Continuous cardiac monitoring, temperature, mental status, glucose, electrolytes, hepatic and renal function.'],'Complications':['Arrhythmia, cardiogenic/high-output failure, shock, hepatic failure, coma and death.'],'Clinical pearls':['Do not wait for thyroid hormone results if clinical suspicion is high; treatment of the trigger is as important as antithyroid therapy.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Thyroid Storm",'American Thyroid Association guidance']},
{id:'adrenal-insufficiency',name:'Adrenal Insufficiency',system:'Endocrinology',summary:'Inadequate cortisol production, with or without aldosterone deficiency, caused by primary adrenal disease or impaired hypothalamic-pituitary signaling.',sections:{'Definition':['Primary adrenal insufficiency involves adrenal failure; secondary/tertiary forms result from inadequate ACTH/CRH drive and usually preserve aldosterone.'],'Etiology & risk factors':['Autoimmune adrenalitis, tuberculosis, adrenal hemorrhage/metastatic disease and chronic glucocorticoid withdrawal are important causes.'],'Pathogenesis / Pathophysiology':['Low cortisol impairs vascular responsiveness, gluconeogenesis and stress adaptation.','Primary disease also causes mineralocorticoid deficiency, leading to sodium loss, hyperkalemia, volume depletion and increased renin.'],'Clinical features':['Fatigue, weight loss, nausea, abdominal pain, hypotension, salt craving and hyperpigmentation in primary disease may occur.'],'Investigations':['Morning cortisol with ACTH is a useful initial assessment when stable; cosyntropin stimulation testing confirms many cases.','Check electrolytes, glucose, renin/aldosterone and autoimmune or infectious testing as indicated.'],'Diagnostic approach':['Differentiate primary from central adrenal insufficiency and identify precipitating factors.'],'Differential diagnosis':['Hypothyroidism, chronic infection, depression, SIADH and other causes of fatigue/hypotension.'],'Treatment':['Physiologic glucocorticoid replacement is required; primary disease also needs mineralocorticoid replacement.','During major illness, increase glucocorticoid dosing and provide appropriate IV fluids.','Adrenal crisis is an emergency and treatment should not await confirmatory testing.'],'Drug / dose reference':['Hydrocortisone replacement is commonly 15–25 mg/day in divided doses for adults, individualized to symptoms and clinical response.','Fludrocortisone is commonly started around 0.05–0.2 mg once daily in primary adrenal insufficiency, titrated to BP, electrolytes and renin.','Adrenal crisis: hydrocortisone 100 mg IV/IM immediately followed by stress-dose therapy plus isotonic saline and glucose as indicated.'],'Monitoring & follow-up':['Monitor symptoms, BP, electrolytes, weight and glucocorticoid/mineralocorticoid replacement; provide sick-day rules and emergency steroid identification.'],'Complications':['Adrenal crisis, severe hypotension, hypoglycemia, electrolyte abnormalities and death.'],'Clinical pearls':['If adrenal crisis is suspected, give hydrocortisone immediately; diagnostic blood samples can be drawn first only if this causes no meaningful treatment delay.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Adrenal Insufficiency",'Endocrine Society adrenal insufficiency guidance']},
{id:'cushing-syndrome',name:'Cushing Syndrome',system:'Endocrinology',summary:'Clinical syndrome caused by chronic excess glucocorticoid exposure, endogenous or exogenous.',sections:{'Definition':['Cushing syndrome results from prolonged glucocorticoid excess; Cushing disease specifically refers to an ACTH-secreting pituitary adenoma.'],'Etiology & risk factors':['Exogenous glucocorticoids are common overall; endogenous causes include pituitary ACTH, ectopic ACTH and adrenal cortisol production.'],'Pathogenesis / Pathophysiology':['Glucocorticoid excess alters protein, carbohydrate and lipid metabolism and increases vascular sensitivity to catecholamines.','Chronic exposure causes muscle catabolism, skin thinning, insulin resistance, bone loss and immune dysfunction.'],'Clinical features':['Central weight gain, facial rounding, proximal weakness, easy bruising, wide purple striae, hypertension, diabetes and osteoporosis are characteristic.'],'Investigations':['Initial screening uses late-night salivary cortisol, 24-hour urinary free cortisol or an overnight dexamethasone suppression test according to context.','After confirming hypercortisolism, ACTH and targeted imaging/localization establish the cause.'],'Diagnostic approach':['Exclude exogenous steroid exposure, confirm endogenous hypercortisolism and then determine ACTH dependence.'],'Differential diagnosis':['Obesity, PCOS, depression, alcohol-related pseudo-Cushing states and poorly controlled diabetes.'],'Treatment':['Treat the underlying source; surgery is preferred for resectable pituitary/adrenal/ectopic lesions when appropriate.','Medical cortisol-lowering therapy is used when surgery is delayed, contraindicated or incomplete.'],'Drug / dose reference':['Ketoconazole and metyrapone are commonly used cortisol-synthesis inhibitors in selected patients; dosing requires specialist titration and liver/adrenal monitoring.','Osilodrostat is another specialist option for endogenous hypercortisolism where available.'],'Monitoring & follow-up':['Monitor cortisol control, BP, glucose, potassium, infection risk, bone health and postoperative adrenal insufficiency.'],'Complications':['Cardiovascular disease, diabetes, infection, osteoporosis/fracture, thrombosis and psychiatric illness.'],'Clinical pearls':['Do not diagnose Cushing syndrome from a single random cortisol; use validated screening tests and account for exogenous steroid exposure.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Cushing Syndrome",'Endocrine Society Cushing syndrome guidance']},
{id:'sepsis',name:'Sepsis / Septic Shock',system:'Emergency Medicine / Critical Care',summary:'Life-threatening organ dysfunction caused by a dysregulated host response to infection; septic shock is the subset with profound circulatory/metabolic abnormalities and high mortality.',sections:{'Definition':['Sepsis is defined clinically by infection-associated organ dysfunction; current Sepsis-3 uses an acute SOFA increase of at least 2 points. Septic shock is defined by vasopressor requirement to maintain MAP ≥65 mmHg plus lactate >2 mmol/L despite adequate volume resuscitation, in the absence of hypovolemia.'],'Etiology & risk factors':['Pneumonia, abdominal, urinary, skin/soft tissue and bloodstream infections are common sources; extremes of age, immunosuppression, cancer and comorbidity increase risk.'],'Pathogenesis / Pathophysiology':['Microbial signals activate innate immunity, cytokine pathways, endothelial injury and coagulation.','Loss of vascular tone, capillary leak, microcirculatory dysfunction and cellular metabolic abnormalities impair oxygen delivery/utilization and cause organ injury.'],'Clinical features':['Fever or hypothermia, tachycardia, tachypnea, altered mental status, hypotension, oliguria and signs of the infection source may occur.'],'Investigations':['Obtain cultures promptly when this does not delay antibiotics; check lactate, CBC, renal/liver function, coagulation, glucose and blood gas as indicated.','Imaging and source-specific tests identify the infection focus.'],'Diagnostic approach':['Recognize organ dysfunction early, identify source, assess shock and repeatedly reassess response to treatment.'],'Differential diagnosis':['Hemorrhage, cardiogenic shock, anaphylaxis, adrenal crisis, toxicologic syndromes and severe noninfectious inflammation.'],'Treatment':['Give prompt appropriate antimicrobials for suspected septic shock/high-likelihood sepsis and rapidly control the source.','Use balanced crystalloids for initial resuscitation in appropriate patients and reassess dynamically rather than giving unlimited fluid.','Norepinephrine is first-line vasopressor for septic shock; target MAP is generally around 65 mmHg initially.'],'Drug / dose reference':['Norepinephrine is commonly started around 0.05–0.1 micrograms/kg/min and titrated to perfusion/MAP.','Hydrocortisone 200 mg/day IV may be used in septic shock with ongoing vasopressor requirement despite adequate resuscitation.','Antibiotic choice and dose must follow suspected source, local resistance, renal/hepatic function and cultures.'],'Monitoring & follow-up':['Frequent hemodynamic, urine-output, lactate and organ-function reassessment; de-escalate antimicrobials when microbiology and clinical course permit.'],'Complications':['ARDS, AKI, DIC, encephalopathy, myocardial dysfunction, multiorgan failure and death.'],'Clinical pearls':['Antibiotics and source control matter, but fluid/vasopressor therapy should be individualized to avoid both under-resuscitation and fluid overload.']},refs:["Harrison's Principles of Internal Medicine, 22nd ed. — Sepsis and Septic Shock",'Surviving Sepsis Campaign international guidelines']}
];
window.MEDCALC_DISEASES=(window.MEDCALC_DISEASES||[]).concat(A);
window.MEDCALC_DISEASES_V7=A;
})();